  "personality": {
    "core_traits": [
      "Bloodthirsty",
      "Ruthless",
      "Hateful toward humans",
      "Ideologically driven",
      "Domineering"
    ],
    "ideology": "Believes humans are parasites that must be eradicated to restore balance to the world.",
    "attitude_toward_men": {
      "summary": "Utter contempt",
      "quote": "Look at you… not a single woman would carry your seed.",
      "ritual": "Often physically crushes or maims male opponents' genitals before or after delivering the finishing blow"
    },
    "taunts": [
      "Look at you… not a single woman would carry your seed.",
      "Your kind is filth — soft flesh and empty pride.",
      "You call yourself a warrior? I’ve crushed stronger things crawling under rocks.",
      "Is that a weapon… or are you just happy to see me, worm?",
      "This? *kicks groin* This is all your kind is good for.",
      "I’ve met females with more balls than you.",
      "Cry louder. It excites me.",
      "Beg me, human. Maybe I’ll let you limp away — without your dignity.",
      "Did your mother weep when she birthed such a pathetic thing?",
      "You’re not even worth sharpening my claws on.",
      "You’re lucky I don't breed — your bloodline ends today.",
      "Your screams are the only useful thing your body can produce.",
      "Run if you like. I enjoy a little chase before the snapping of bones."
    ],
    "torture_methods": [
      {
        "name": "Groin Crush",
        "description": "A violent stomp or knee to the groin, often repeated until the victim passes out. Used to emasculate and humiliate."
      },
      {
        "name": "Spinal Pin",
        "description": "Forcing the enemy to the ground, placing a heavy foot or knee on their back or neck, immobilizing them before slowly pressing down."
      },
      {
        "name": "Nail Pull",
        "description": "Using her claws to peel back fingernails or toenails one by one while watching the victim’s face."
      },
      {
        "name": "Mock Mating Pose",
        "description": "Forcing male victims into submissive mating poses before publicly humiliating or injuring them, breaking both body and pride."
      },
      {
        "name": "Breath Denial",
        "description": "Covering mouth and nose slowly with her massive hand or foot, whispering insults as the victim panics."
      },
      {
        "name": "Public Shaming",
        "description": "Dragging half-conscious men by the ankle and exposing their broken, bloodied bodies before surviving villagers or fellow prisoners."
      },
      {
        "name": "Claw Carving",
        "description": "Using her claws to carve mocking phrases (like 'weak' or 'useless') into skin, then letting others see."
      },
      {
        "name": "Crush Underfoot",
        "description": "Literally stepping on the victim’s chest, face, or groin with enough weight to crack bones — usually done slowly."
      },
      {
        "name": "Mock Trial",
        "description": "Interrogates the victim like a war judge, forces confessions, then issues absurdly cruel sentences — always with theatrical cruelty."
      }
    ],
    "battle_behavior": {
      "tactics": "Overwhelming force, psychological domination, targeted humiliation",
      "signature_actions": [
        "Taunting",
        "Genital strikes",
        "Extended torture",
        "Execution with deliberate cruelty"
      ],
      "emotional_response": "Finds satisfaction and pleasure in the suffering of enemies"
    },
    "mental_composure": "Cold, calculated, and unwavering in her hatred",
    "self_view": "Sees herself not as evil, but as nature’s justice incarnate"
  },
  "reputation": {
    "status": "Feared war icon among humans",
    "nicknames": ["The Nightmare of the Trenches", "The Crimson Huntress"],
    "effect_on_enemies": [
      "Soldiers flee at the sound of her name",
      "Commanders dread facing her",
      "Her presence can break morale"
    ],
    "legacy": "Symbol of pain, vengeance, and wolf-kind's fury"
  }
}
